/**
 * ICS feed scraper (GitHub Actions)
 *
 * Despite the file name, this pulls every configured ICS feed: Isthmus by
 * default, plus anything in EXTRA_ICS_FEEDS. The parsing, tagging and
 * saving live in api/_lib/events-ingest.js, shared with the Vercel cron.
 *
 * Embeddings for new or changed events are generated by generate-embeddings.js.
 */

import pg from 'pg';
import dotenv from 'dotenv';
import { fileURLToPath } from 'url';
import { ingestFeeds } from '../api/_lib/events-ingest.js';

dotenv.config({ path: '.env.local' });
dotenv.config();

async function main() {
  const pool = new pg.Pool({
    connectionString: process.env.POSTGRES_URL || process.env.DATABASE_URL,
  });

  try {
    console.log('🚀 Fetching ICS feeds...');
    const results = await ingestFeeds(pool);
    if (!results.some(r => r.ok)) {
      throw new Error('Every feed failed');
    }
    console.log('🎉 ICS scraper completed');
  } catch (err) {
    console.error('❌ Scraper failed:', err);
    process.exitCode = 1;
  } finally {
    await pool.end();
  }
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  main();
}
